CREATE TABLE sac_t (id int, v int);
CREATE TABLE sac_u (v int);
INSERT INTO sac_t VALUES (1, 10), (2, 20), (3, 30);
INSERT INTO sac_u VALUES (5), (6);
SELECT sum((SELECT v FROM sac_u ORDER BY v LIMIT 1)) FROM sac_t;
SELECT count((SELECT 1)), max((SELECT 'a'::text)), avg((SELECT 2.5)) FROM sac_t;
SELECT sum((SELECT sac_u.v + sac_t.v FROM sac_u ORDER BY sac_u.v LIMIT 1)) FROM sac_t;
SELECT string_agg((SELECT 'x'), ',') FROM sac_t;
SELECT id, sum(v) OVER (), (SELECT count(*) FROM sac_u WHERE sac_u.v < sum(sac_t.v)) FROM sac_t GROUP BY id ORDER BY id;
SELECT id, sum(v) OVER (), (SELECT count(*) FROM sac_u WHERE sac_u.v < sum(sac_t.v)) FROM sac_t GROUP BY id, v ORDER BY id;
SELECT id, row_number() OVER (ORDER BY id), (SELECT max(sac_t.v)) FROM sac_t GROUP BY id ORDER BY id;
SELECT (SELECT max(sac_t.v)), rank() OVER () FROM sac_t;
SELECT id, sum((SELECT max(sac_t.v))) OVER (ORDER BY id) FROM sac_t GROUP BY id ORDER BY id;
SELECT (SELECT max(sac_t.v) + count(*) FROM sac_u), rank() OVER () FROM sac_t;
SELECT id, (SELECT sac_t.v), rank() OVER () FROM sac_t GROUP BY id;
SELECT id, (SELECT sac_t.id * 2), rank() OVER (ORDER BY id DESC) FROM sac_t GROUP BY id ORDER BY id;
SELECT count(*) OVER (), EXISTS (SELECT 1 FROM sac_u WHERE sac_u.v < max(sac_t.v)) FROM sac_t;
SELECT v, rank() OVER (ORDER BY (SELECT sac_t.v)) FROM sac_t GROUP BY v ORDER BY v;
SELECT id, sum(v) OVER (ORDER BY id) FROM sac_t GROUP BY id ORDER BY (SELECT max(sac_t.v)) DESC;
CREATE VIEW sac_view AS SELECT id, (SELECT max(sac_u.v) FROM sac_u WHERE sac_u.v > sac_t.id) AS m FROM sac_t;
SELECT * FROM sac_view ORDER BY id;
CREATE VIEW sac_view2 AS SELECT id, (SELECT count(*) FROM sac_u WHERE EXISTS (SELECT 1 FROM sac_t t2 WHERE t2.v = sac_t.v)) AS c FROM sac_t;
SELECT * FROM sac_view2 ORDER BY id;
SELECT refobjid::regclass, refobjsubid FROM pg_depend WHERE objid = (SELECT oid FROM pg_rewrite WHERE ev_class = 'sac_view'::regclass) AND refobjid <> 'sac_view'::regclass ORDER BY refobjid::regclass::text, 2;
DROP TABLE sac_u;
